import { greet, slugify } from "./index";

test("greet returns a greeting with the given name", () => {
  expect(greet("World")).toBe("Hello, World!");
});

test("slugify lowercases and hyphenates words", () => {
  expect(slugify("Hello, World!")).toBe("hello-world");
});

test("slugify collapses runs of non-alphanumeric characters into one hyphen", () => {
  expect(slugify("foo---bar   baz__qux")).toBe("foo-bar-baz-qux");
});

test("slugify trims surrounding whitespace", () => {
  expect(slugify("  Hello World  ")).toBe("hello-world");
});

