});

test("slugify keeps digits", () => {
  expect(slugify("Version 42 Release")).toBe("version-42-release");
});

test("slugify returns an empty string when there are no alphanumeric characters", () => {
  expect(slugify("!!! ??  ")).toBe("");
  expect(slugify("")).toBe("");
