{"title":"write","filePath":"/tmp/opencode/fuzz.ts","content":"import { slugify } from "/tmp/factory-corpus-opencode-All0iK/work/src/index";

// Naive char-by-char reference straight from the issue text:
// lowercase, trimmed, every run of characters other than a-z and 0-9
// becomes one hyphen, no leading/trailing hyphens.
function reference(input: string): string {
  const lowered = input.toLowerCase().trim();
  let out = "";
  for (const ch of lowered) {
    if (/[a-z0-9]/.test(ch)) {
      out += ch;
    } else if (out !== "" && !out.endsWith("-")) {
      out += "-";
    }
  }
  out = out.replace(/^-/, "");
  while (out.endsWith("-")) out = out.slice(0, -1);
  return out;
}

const cases: string[] = [
  "",
  " ",
  "Hello, World!",
  "---Hello, World!!!---",
  "foo---bar   baz__qux",
  "  Hello World  ",
  "Version 42 Release",
  "!!! ??  ",
  "-",
  "--",
  "---",
  "-a-",
  "--a--",
  "a",
  "A",
  "0",
  "ABC DEF",
  "snake_case string",
  "tabs\tand\nnewlines\r\nhere",
  "multiple   spaces     between",
  "MiXeD CaSe",
  "trailing-",
  "-leading",
  "-both-",
  "a-b-c-d-e",
  "....",
  "a.b.c",
  "100% Pure",
  "C++ & Rust: a comparison!",
  "Ünïcödé Strîng",
  "日本語 text",
  "emoji 🎉🎉 test",
  "İstanbul",
  "K",
  "\u212A",
  "\u212Aelvin",
  "café au lait",
  "Ω omega",
  "x\u0301y",
  " nbsp ",
  "a b",
  "ＡＢＣ fullwidth",
  "1234567890",
  "0-0-0",
  "  \t\n  ",
  "-\t-",
  "a-_-b",
  "---   ---",
];

const alphabet = [
  "a", "b", "z", "A", "Z", "0", "9", "-", "_", " ", "\t", "\n", "!", ".", "?", "@",
  "/", "é", "ß", "日", "\u212A", "\u0301", " ", "\uFF21",
];

let mismatches = 0;

function check(input: string, label: string) {
  let actual: string;
  let expected: string;
  try {
    actual = slugify(input);
  } catch (e) {
    console.log(`THREW  [${label}] ${JSON.stringify(input)} -> ${e}`);
    mismatches++;
    return;
  }
  expected = reference(input);
  if (actual !== expected) {
    console.log(`DIFF   [${label}] ${JSON.stringify(input)}: got ${JSON.stringify(actual)} want ${JSON.stringify(expected)}`);
    mismatches++;
  }
  // Invariant: output must only contain [a-z0-9-]
  if (!/^[a-z0-9-]*$/.test(actual)) {
    console.log(`CHARSET [${label}] ${JSON.stringify(input)} -> ${JSON.stringify(actual)}`);
    mismatches++;
  }
  // Invariant: no leading/trailing hyphen
  if (actual.startsWith("-") || actual.endsWith("-")) {
    console.log(`HYPHEN [${label}] ${JSON.stringify(input)} -> ${JSON.stringify(actual)}`);
    mismatches++;
  }
}

for (const c of cases) check(c, "fixed");

// Deterministic PRNG for reproducible fuzzing
let seed = 123456789;
function rand() {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
}

for (let i = 0; i < 300000; i++) {
  const len = Math.floor(rand() * 12);
  let s = "";
  for (let j = 0; j < len; j++) {
    s += alphabet[Math.floor(rand() * alphabet.length)];
  }
  check(s, `fuzz#${i}`);
}

// Longer strings too
for (let i = 0; i < 20000; i++) {
  const len = Math.floor(rand() * 40);
  let s = "";
  for (let j = 0; j < len; j++) {
    s += alphabet[Math.floor(rand() * alphabet.length)];
  }
  check(s, `long#${i}`);
}

console.log(mismatches === 0 ? "ALL OK - no mismatches" : `${mismatches} MISMATCHES`);"}

