{"output":"diff --git a/src/index.test.ts b/src/index.test.ts
index 99b148a..2e929f9 100644
--- a/src/index.test.ts
+++ b/src/index.test.ts
@@ -1,6 +1,31 @@
 import { expect, test } from "bun:test";
-import { greet } from "./index";
+import { greet, slugify } from "./index";

 test("greet returns a greeting with the given name", () => {
   expect(greet("World")).toBe("Hello, World!");
 });
+
+test("slugify lowercases and hyphenates words", () => {
+  expect(slugify("Hello, World!")).toBe("hello-world");
+});
+
+test("slugify collapses runs of non-alphanumeric characters into one hyphen", () => {
+  expect(slugify("foo---bar   baz__qux")).toBe("foo-bar-baz-qux");
+});
+
+test("slugify trims surrounding whitespace", () => {
+  expect(slugify("  Hello World  ")).toBe("hello-world");
+});
+
+test("slugify strips leading and trailing hyphens", () => {
+  expect(slugify("---Hello, World!!!---")).toBe("hello-world");
+});
+
+test("slugify keeps digits", () => {
+  expect(slugify("Version 42 Release")).toBe("version-42-release");
+});
+
+test("slugify returns an empty string when there are no alphanumeric characters", () => {
+  expect(slugify("!!! ??  ")).toBe("");
+  expect(slugify("")).toBe("");
+});
diff --git a/src/index.ts b/src/index.ts
index 264d785..53c6377 100644
--- a/src/index.ts
+++ b/src/index.ts
@@ -2,3 +2,12 @@
 export function greet(name: string): string {
   return `Hello, ${name}!`;
 }
+
+/** Returns a URL-friendly slug for the given input. */
+export function slugify(input: string): string {
+  return input
+    .toLowerCase()
+    .trim()
+    .replace(/[^a-z0-9]+/g, "-")
+    .replace(/^-+|-+$/g, "");
+}
